package local.pocketchat;
import android.content.Context;import android.os.*;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;import java.util.concurrent.*;

public final class Worker46Cases {
 static final JSONArray checks=new JSONArray(),measurements=new JSONArray();static void check(String name,boolean pass){checks.put(J.obj("name",name,"pass",pass));if(!pass)throw new AssertionError(name);}
 static String ownerId(int slot){return "00000000-0000-0000-0000-00000000000"+slot;}
 static void owners(){ProfileCatalog.db=new SQLiteDatabase();for(int slot=0;slot<8;slot++)ProfileCatalog.db.add("environments",J.obj("slot",slot,"name","环境 "+slot,"environment_id",ownerId(slot),"generation",1,"created",1,"deleting",0,"resetting",0));}
 static String label(DownloadDisplayCache.Page page,String id){return page.environmentLabels.get("0:id:"+id);}
 static DownloadDisplayCache.Page read(String anchor)throws Exception{CompletableFuture<DownloadDisplayCache.Page> complete=new CompletableFuture<>();new Handler(Looper.getMainLooper()).post(()->DownloadDisplayCache.request(new Context(),0,anchor,"",complete::complete,complete::completeExceptionally));return complete.get(20,TimeUnit.SECONDS);}
 public static void main(String[] args)throws Exception{Throwable failure=null;try{
  for(int count:new int[]{100,1000,10000}){DownloadLibrary.instance=new DownloadLibrary();owners();SQLiteDatabase db=DownloadLibrary.instance.db;for(int i=0;i<count;i++)db.add("files",J.obj("id","file"+i,"slot",i%8,"state","saved","uri","content://fixture/"+i,"time",i+1,"name","file.txt","environmentId",ownerId(i%8),"environmentGeneration",1));db.add("tasks",J.obj("id","active","slot",0,"state","downloading","uri","","time",count+1,"received",1,"environmentId",ownerId(0),"environmentGeneration",1));DownloadLibraryChanges.revision.incrementAndGet();ProfileCatalog.calls=ProfileCatalog.mainCalls=AppUpdates.mainCalls=AppUpdates.calls=0;
    DownloadDisplayCache.Page first=read("");check(count+" first snapshot executes exactly one worker statement",db.queries==1&&db.mainQueries==0&&ProfileCatalog.calls==1&&ProfileCatalog.mainCalls==0);check(count+" owner/name map uses one exact seven-column worker projection",ProfileCatalog.db.queries==1&&ProfileCatalog.db.mainQueries==0&&Arrays.equals(ProfileCatalog.db.ownerProjection,new String[]{"slot","name","environment_id","generation","created","deleting","resetting"}));check(count+" prepared page/time/name data are bounded and complete",first.window.total==count+1&&first.window.rows.length()==40&&first.times.size()==40&&first.names.size()==8);
    DownloadDisplayCache.Page same=read("");check(count+" unchanged refresh executes no full statement or name read",db.queries==1&&ProfileCatalog.calls==1&&same.window==first.window);check(count+" package status uses worker provider and remains fresh",AppUpdates.mainCalls==0&&AppUpdates.calls==2&&same.update.getLong("packageStoredBytes")==2);
    DownloadDisplayCache.Page next=read(first.window.next);check(count+" on-demand page uses cached complete data without SQL",db.queries==1&&next.window.rows.length()==40&&next.window.start==40);
    db.add("files",J.obj("id","new-record","slot",0,"state","saved","uri","content://fixture/new","time",count+10,"name","new.txt"));DownloadLibraryChanges.revision.incrementAndGet();DownloadDisplayCache.Page dirty=read(first.window.next);check(count+" dirty event rebuilds with one statement and preserves page anchor",db.queries==2&&dirty.window.rows.getJSONObject(0).optString("id").equals(next.window.rows.getJSONObject(0).optString("id")));
    measurements.put(J.obj("historyRows",count,"mainSqlCalls",db.mainQueries,"mainProviderCalls",AppUpdates.mainCalls,"mainEnvironmentQueries",ProfileCatalog.mainCalls,"initialSnapshotStatements",1,"unchangedSnapshotStatements",0,"dirtySnapshotStatements",1,"pageSize",40,"actualPhoneMeasurement",false));
  }
  DownloadLibrary.instance=new DownloadLibrary();owners();SQLiteDatabase files=DownloadLibrary.instance.db;files.add("files",J.obj("slot",0,"id","owned","state","saved","uri","content://fixture/owned","time",1,"environmentId",ownerId(0),"environmentGeneration",1));files.add("files",J.obj("slot",0,"id","legacy","state","saved","uri","content://fixture/legacy","time",2));DownloadLibraryChanges.revision.incrementAndGet();DownloadDisplayCache.Page owned=read("");check("Worker labels matching owner with its current name",label(owned,"owned").equals("环境 0"));check("Worker labels legacy ownership unconfirmed",label(owned,"legacy").equals("归属待确认"));Map<String,Object> owner=ProfileCatalog.db.tables.get("environments").get(0);
  owner.put("name","已改名");DownloadLibraryChanges.revision.incrementAndGet();check("Worker rename only follows matching owner",label(read(""),"owned").equals("已改名"));
  owner.put("created",0);DownloadLibraryChanges.revision.incrementAndGet();DownloadDisplayCache.Page deleted=read("");check("Worker retains file after deletion with historical label",label(deleted,"owned").equals("原环境（已删除）"));check("Deleted slot does not manufacture legacy ownership",label(deleted,"legacy").equals("归属待确认"));
  String nextId="10000000-0000-0000-0000-000000000000";owner.put("created",1);owner.put("environment_id",nextId);owner.put("generation",2);owner.put("name","新主人");DownloadLibraryChanges.revision.incrementAndGet();DownloadDisplayCache.Page reused=read("");check("Worker slot reuse never relabels old file as new owner",label(reused,"owned").equals("原环境（已重建）"));check("Worker slot reuse leaves legacy ownership unconfirmed",label(reused,"legacy").equals("归属待确认"));
  files.add("files",J.obj("slot",0,"id","new-owner-file","state","saved","uri","content://fixture/new-owner","time",3,"environmentId",nextId,"environmentGeneration",2));DownloadLibraryChanges.revision.incrementAndGet();check("Worker labels the new owner's own file correctly",label(read(""),"new-owner-file").equals("新主人"));
 }catch(Throwable error){failure=error;}JSONObject report=J.obj("status",failure==null?"passed":"failed","checks",checks,"total",checks.length(),"measurements",measurements,"actualAndroidExecution",false,"actualSqliteExecution",false,"phonePerformanceMeasured",false,"scope","Complete production display cache/snapshot/page code on real serial JVM worker and main queue with counted deterministic SQLite, catalog and update-provider adapters. No Android disk/scheduling/FPS claim.");if(failure!=null)report.put("error",failure.toString());System.out.println(report.toString(2));if(failure!=null)System.exit(1);}
}
class DownloadLibrary {static DownloadLibrary instance;final SQLiteDatabase db=new SQLiteDatabase();static DownloadLibrary get(Context c){return instance;}void migrate(){}void migrateTasks(){}SQLiteDatabase getReadableDatabase(){return db;}}
class DownloadLibraryChanges {static final java.util.concurrent.atomic.AtomicLong revision=new java.util.concurrent.atomic.AtomicLong();}
class ProfileCatalog {static int calls,mainCalls;static SQLiteDatabase db;static ProfileCatalog get(Context c){return new ProfileCatalog();}SQLiteDatabase getReadableDatabase(){return db;}Map<Integer,String> names(){throw new AssertionError("Display cache must use the owner projection");}}
class UiPerfStats{static void catalogRead(){ProfileCatalog.calls++;if(Looper.myLooper()==Looper.getMainLooper())ProfileCatalog.mainCalls++;}}
class Profiles {static Context global(Context c){return c;}}
class AppUpdates {static int calls,mainCalls;static Bundle call(Context c,String method,Bundle ignored){calls++;if(Looper.myLooper()==Looper.getMainLooper())mainCalls++;Bundle b=new Bundle();b.putLong("packageStoredBytes",calls);return b;}}
